// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address nonOwner, uint256 amount, bytes calldata data) public {
        vm.assume(nonOwner != c.Owner());
        vm.assume(amount <= address(this).balance);

        vm.deal(nonOwner, amount);

        bool ok;
        try this.callCommandThroughC(nonOwner, amount, data) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "non-owner call should fail");
    }

    function callCommandThroughC(address caller, uint256 amount, bytes calldata data) external returns (bool) {
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSelector(MultiplicatorX4.Command.selector, address(this), data));
        return success;
    }
}
